export function AccessDenied({
  resource = "{{resource}}",
  reason = "{{reason}}",
  showContact = {{showContact}},
  contactLabel = "{{contactLabel}}",
  accent = "{{accent}}",
}) {
  const reasonText = {
    role: `Your account role doesn't include access to ${resource}.`,
    trial: `${resource} needs an upgraded plan to open.`,
    region: `${resource} isn't available in your region yet.`,
  }[reason];
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", maxWidth: 360, boxSizing: "border-box", padding: 24, borderRadius: 14,
      border: "1.5px solid #24143020", textAlign: "center" }}>
      <div aria-hidden="true" style={{ display: "inline-flex", alignItems: "center", justifyContent: "center",
        width: 52, height: 52, borderRadius: "50%", background: `color-mix(in srgb, ${accent} 16%, #FAF7F2)`,
        color: accent, marginBottom: 12 }}>
        <svg width="26" height="26" viewBox="0 0 24 24" fill="none"><rect x="5" y="11" width="14" height="10" rx="2" fill="currentColor"/><path d="M8 11V7a4 4 0 0 1 8 0v4" stroke="currentColor" strokeWidth="2" fill="none"/></svg>
      </div>
      <h3 style={{ margin: "0 0 8px", fontSize: 18, fontWeight: 700 }}>Access denied</h3>
      <p style={{ margin: "0 0 10px", color: "#241430cc" }}>You don't have permission to open <strong>{resource}</strong>.</p>
      <p style={{ margin: "0 0 16px", fontSize: 13, color: "#241430aa" }}>{reasonText}</p>
      {showContact && (
        <button type="button" style={{ background: accent, color: "#FAF7F2", border: "none", padding: "10px 20px",
          borderRadius: 8, fontWeight: 600, fontSize: 14, cursor: "pointer" }}>{contactLabel}</button>
      )}
    </div>
  );
}
